//! Port of `flex2.compiler.media.PBJTranscoder`: a Pixel Bender kernel as a `Shader` over a generated byte array.

use super::abstract_transcoder::{new_results, resolve_source, AbstractTranscoder};
use super::data_transcoder::DataTranscoder;
use crate::asc::flex2::compiler::symbol_table::SymbolTable;
use crate::asc::flex2::compiler::transcoder::{self, Args, PathResolver, ResultsRef, Transcoder, TranscoderException, TranscodingResults};
use crate::asc::flex2::flash::swf::tags::TagRef;

pub struct PbjTranscoder {
    base: AbstractTranscoder,
}

impl Default for PbjTranscoder {
    fn default() -> Self {
        Self::new()
    }
}

impl PbjTranscoder {
    pub fn new() -> PbjTranscoder {
        PbjTranscoder { base: AbstractTranscoder::new(&[super::mime::PBJ], None, true, "flex2.compiler.media.PBJTranscoder") }
    }

    fn do_transcode(context: &PathResolver, args: &mut Args, class_name: &str, generate_source: bool) -> Result<ResultsRef, TranscoderException> {
        let source = resolve_source(context, args)?;
        let byte_array_class_name = format!("{class_name}ByteArray");
        args.insert(transcoder::NEWNAME.to_string(), byte_array_class_name.clone());
        let byte_array_results = DataTranscoder::do_transcode(context, args, &byte_array_class_name, generate_source)?;
        byte_array_results.borrow_mut().class_name = Some(byte_array_class_name.clone());
        let mut shader = TranscodingResults::with_source(source);
        shader.class_name = Some(class_name.to_string());
        if generate_source {
            shader.generated_code = Some(Self::generate_source(class_name, &byte_array_class_name));
        }
        shader.additional_assets = Some(vec![byte_array_results]);
        Ok(new_results(shader))
    }

    fn generate_source(full_class_name: &str, byte_array_class_name: &str) -> String {
        let package_name = full_class_name.replace(':', ".").rfind('.').map_or(String::new(), |i| full_class_name[..i].to_string());
        let class_name = crate::asc::flex2::compiler::util::name_formatter::retrieve_class_name(full_class_name);
        let mut sb = String::new();
        sb.push_str(&format!("package {package_name}\n"));
        sb.push_str("{\n");
        sb.push_str("import flash.display.Shader;\n");
        sb.push_str("import flash.utils.ByteArray;\n");
        sb.push_str("import mx.core.IFlexAsset;\n");
        if !package_name.is_empty() {
            sb.push_str(&format!("import {byte_array_class_name};\n"));
        }
        sb.push('\n');
        sb.push_str(&format!("public class {class_name} extends Shader implements IFlexAsset\n"));
        sb.push_str("{\n");
        sb.push_str(&format!("\tpublic function {class_name}()\n"));
        sb.push_str("    {\n");
        sb.push_str("        super();\n");
        sb.push_str(&format!("        byteCode = new {byte_array_class_name}();\n"));
        sb.push_str("    }\n");
        sb.push_str("}\n");
        sb.push_str("}\n");
        sb
    }
}

impl Transcoder for PbjTranscoder {
    fn is_supported(&self, mime_type: &str) -> bool {
        self.base.is_supported(mime_type)
    }

    fn transcode(&mut self, context: &PathResolver, _symbol_table: Option<&SymbolTable>, args: &mut Args, class_name: &str, generate_source: bool) -> Result<ResultsRef, TranscoderException> {
        self.base.transcode(args, &|_| false, &mut |args| Self::do_transcode(context, args, class_name, generate_source))
    }

    fn get_associated_class(&self, tag: Option<&TagRef>) -> Option<String> {
        self.base.get_associated_class(tag)
    }

    fn clear(&mut self) {
        self.base.clear();
    }
}
